import { useLocalSearchParams } from 'expo-router';
import { PublicBioScreen } from '@/src/features/bio/PublicBioScreen';
import { DemoBioScreen } from '@/src/features/bio/DemoBioScreen';

/**
 * Direct chip NFC / QR scan target route: /c/{cardId}.
 * Matches URLs generated by buildCardProfileUrl(cardId).
 * Automatically resolves profile by cardId or slug from Firestore.
 */
export default function CardPublicRoute() {
  const params = useLocalSearchParams<{ cardId: string }>();
  const cardId = typeof params.cardId === 'string' ? params.cardId : '';

  if (cardId === 'demo') return <DemoBioScreen />;

  return <PublicBioScreen cardId={cardId} slug={cardId} />;
}
